                if (!amount.isEmpty() && !amount.matches(AMOUNT)) {
                    throw new InvalidSettingException("The proof threshold of grade " + grade
                            + " must be an amount, 0.00 or more, with up to two decimals, or blank for the sheet's.");
                }
