        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = history.gradeTermsOn(grade, today);
            if (days != null) {
                gradeTerms.put(grade, days);
            }
