-- A sheet: the unit everything else in the app is kept under. Created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- The sheet's pools: a name (trimmed) at most once on a sheet, and the day it was added (the sheet's today then).
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name     VARCHAR(200) NOT NULL,
    added_by VARCHAR(100) NOT NULL,
    added_on DATE,
    CONSTRAINT pool_name UNIQUE (sheet_id, name)
);

-- A pool's members: a person at most once in a pool, with their share percent (more than 0.00, at most 100.00).
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet(id),
            placeholder="yyyy-mm-dd"
            value={typed}
            onChange={(e) => {
              setTyped(e.target.value);
              save.reset();
              archive.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
          Set today
        </button>
      </form>
      <p>
        Archived <strong data-testid="sheet-archived">{sheet.data ? (sheet.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
        <button
          type="button"
          data-testid="sheet-archive"
          disabled={archive.isPending}
          onClick={() => {
            if (!once.start()) return;
            save.reset();
            archive.reset();
            archive.mutate();
          }}
        >
